public boolean isEvenOddTree(TreeNode root) {
    Queue<TreeNode> q = new LinkedList<>();
    q.offer(root);
    int level = 0;
    while (!q.isEmpty()) {
        int size = q.size();
        int prev = (level % 2 == 0) ? Integer.MIN_VALUE : Integer.MAX_VALUE;
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            int val = node.val;
            if (level % 2 == 0) {
                if (val % 2 == 0 || val <= prev) return false; // must be odd, increasing
            } else {
                if (val % 2 != 0 || val >= prev) return false; // must be even, decreasing
            }
            prev = val;
            if (node.left  != null) q.offer(node.left);
            if (node.right != null) q.offer(node.right);
        }
        level++;
    }
    return true;
}

public TreeNode addOneRow(TreeNode root, int val, int depth) {
    if (depth == 1) {
        TreeNode newRoot = new TreeNode(val);
        newRoot.left = root;
        return newRoot;
    }
    Queue<TreeNode> q = new LinkedList<>();
    q.offer(root);
    int curDepth = 1;
    while (!q.isEmpty()) {
        int size = q.size();
        if (curDepth == depth - 1) {
            for (int i = 0; i < size; i++) {
                TreeNode node = q.poll();
                TreeNode newLeft  = new TreeNode(val);
                TreeNode newRight = new TreeNode(val);
                newLeft.left   = node.left;
                newRight.right = node.right;
                node.left  = newLeft;
                node.right = newRight;
            }
            return root;
        }
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            if (node.left  != null) q.offer(node.left);
            if (node.right != null) q.offer(node.right);
        }
        curDepth++;
    }
    return root;
}

public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> q = new LinkedList<>();
    q.offer(root);
    boolean leftToRight = true;
    while (!q.isEmpty()) {
        int size = q.size();
        LinkedList<Integer> level = new LinkedList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            if (leftToRight) level.addLast(node.val);
            else             level.addFirst(node.val);
            if (node.left  != null) q.offer(node.left);
            if (node.right != null) q.offer(node.right);
        }
        res.add(level);
        leftToRight = !leftToRight;
    }
    return res;
}

public TreeNode reverseOddLevels(TreeNode root) {
    Queue<TreeNode> q = new LinkedList<>();
    q.offer(root);
    int level = 0;
    while (!q.isEmpty()) {
        int size = q.size();
        List<TreeNode> nodes = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            nodes.add(node);
            if (node.left  != null) q.offer(node.left);
            if (node.right != null) q.offer(node.right);
        }
        if (level % 2 == 1) {
            int lo = 0, hi = nodes.size() - 1;
            while (lo < hi) {
                int tmp = nodes.get(lo).val;
                nodes.get(lo).val = nodes.get(hi).val;
                nodes.get(hi).val = tmp;
                lo++; hi--;
            }
        }
        level++;
    }
    return root;
}

