public List<List<Integer>> verticalTraversal(TreeNode root) {
    TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map = new TreeMap<>();
    Queue<Object[]> q = new LinkedList<>();
    q.offer(new Object[]{root, 0, 0});          // node, col, row
    while (!q.isEmpty()) {
        Object[] curr = q.poll();
        TreeNode node = (TreeNode) curr[0];
        int col = (int) curr[1], row = (int) curr[2];
        map.computeIfAbsent(col, k -> new TreeMap<>())
           .computeIfAbsent(row, k -> new PriorityQueue<>())
           .offer(node.val);
        if (node.left  != null) q.offer(new Object[]{node.left,  col-1, row+1});
        if (node.right != null) q.offer(new Object[]{node.right, col+1, row+1});
    }
    List<List<Integer>> res = new ArrayList<>();
    for (var colMap : map.values()) {
        List<Integer> colList = new ArrayList<>();
        for (var pq : colMap.values())
            while (!pq.isEmpty()) colList.add(pq.poll());
        res.add(colList);
    }
    return res;
}

public int widthOfBinaryTree(TreeNode root) {
    if (root == null) return 0;
    int maxWidth = 0;
    Queue<Object[]> q = new LinkedList<>();
    q.offer(new Object[]{root, 0L});
    while (!q.isEmpty()) {
        int size = q.size();
        long first = 0, last = 0;
        for (int i = 0; i < size; i++) {
            Object[] curr = q.poll();
            TreeNode node = (TreeNode) curr[0];
            long idx = (long) curr[1];
            if (i == 0) first = idx;
            last = idx;
            long norm = idx - first;             // normalize to prevent overflow
            if (node.left  != null) q.offer(new Object[]{node.left,  2 * norm});
            if (node.right != null) q.offer(new Object[]{node.right, 2 * norm + 1});
        }
        maxWidth = (int) Math.max(maxWidth, last - first + 1);
    }
    return maxWidth;
}

public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
    Map<TreeNode, TreeNode> parent = new HashMap<>();
    buildParents(root, null, parent);
    Queue<TreeNode> q = new LinkedList<>();
    Set<TreeNode> visited = new HashSet<>();
    q.offer(target); visited.add(target);
    int dist = 0;

    while (!q.isEmpty() && dist < k) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            for (TreeNode nb : new TreeNode[]{node.left, node.right, parent.get(node)}) {
                if (nb != null && !visited.contains(nb)) {
                    visited.add(nb);
                    q.offer(nb);
                }
            }
        }
        dist++;
    }
    List<Integer> res = new ArrayList<>();
    while (!q.isEmpty()) res.add(q.poll().val);
    return res;
}

private void buildParents(TreeNode node, TreeNode par, Map<TreeNode, TreeNode> parent) {
    if (node == null) return;
    parent.put(node, par);
    buildParents(node.left,  node, parent);
    buildParents(node.right, node, parent);
}

