private TreeNode build(int[] pre, int preS, int preE, int inS, int inE) {
    if (preS > preE) return null;
    int rootVal = pre[preS];
    TreeNode root = new TreeNode(rootVal);
    int inRoot   = inMap.get(rootVal);
    int leftSize = inRoot - inS;                  // number of nodes in left subtree
    root.left  = build(pre, preS + 1, preS + leftSize, inS, inRoot - 1);
    root.right = build(pre, preS + leftSize + 1, preE, inRoot + 1, inE);
    return root;
}

