private TreeNode build(int[] post, int postS, int postE, int inS, int inE) {
    if (postS > postE) return null;
    int rootVal  = post[postE];
    TreeNode root = new TreeNode(rootVal);
    int inRoot   = inMap.get(rootVal);
    int leftSize = inRoot - inS;
    root.left  = build(post, postS, postS + leftSize - 1, inS, inRoot - 1);
    root.right = build(post, postS + leftSize, postE - 1, inRoot + 1, inE);
    return root;
}

public TreeNode constructMaximumBinaryTree(int[] nums) {
    return build(nums, 0, nums.length - 1);
}

private TreeNode build(int[] nums, int lo, int hi) {
    if (lo > hi) return null;
    int maxIdx = lo;
    for (int i = lo + 1; i <= hi; i++)
        if (nums[i] > nums[maxIdx]) maxIdx = i;
    TreeNode root = new TreeNode(nums[maxIdx]);
    root.left  = build(nums, lo, maxIdx - 1);
    root.right = build(nums, maxIdx + 1, hi);
    return root;
}

