private TreeNode build(int[] pre, int min, int max) {
    if (idx == pre.length || pre[idx] < min || pre[idx] > max) return null;
    int val = pre[idx++];
    TreeNode root = new TreeNode(val);
    root.left  = build(pre, min, val);      // left subtree: values < val
    root.right = build(pre, val, max);      // right subtree: values > val
    return root;
}

