// Returns [LCA node, max depth from this node]
private Map.Entry<TreeNode, Integer> dfs(TreeNode node) {
    if (node == null) return new AbstractMap.SimpleEntry<>(null, 0);
    var left  = dfs(node.left);
    var right = dfs(node.right);
    int ld = left.getValue(), rd = right.getValue();
    if (ld == rd) return new AbstractMap.SimpleEntry<>(node, ld + 1);
    if (ld >  rd) return new AbstractMap.SimpleEntry<>(left.getKey(),  ld + 1);
    return             new AbstractMap.SimpleEntry<>(right.getKey(), rd + 1);
}

int[][] up;
int LOG = 16;

public TreeAncestor(int n, int[] parent) {
    up = new int[n][LOG];
    for (int[] row : up) Arrays.fill(row, -1);
    for (int i = 0; i < n; i++) up[i][0] = parent[i];   // direct parent
    for (int j = 1; j < LOG; j++)
        for (int i = 0; i < n; i++)
            if (up[i][j-1] != -1) up[i][j] = up[up[i][j-1]][j-1];
}

public int getKthAncestor(int node, int k) {
    for (int j = 0; j < LOG; j++) {
        if ((k >> j & 1) == 1) {            // if j-th bit of k is set
            node = up[node][j];
            if (node == -1) return -1;
        }
    }
    return node;
}

public boolean isValidBST(TreeNode root) {
