    prev = node;
    inorder(node.right);
}

public int rob(TreeNode root) {
    int[] res = dfs(root);
    return Math.max(res[0], res[1]);
}

// returns [maxIfRobbed, maxIfNotRobbed]
private int[] dfs(TreeNode node) {
    if (node == null) return new int[]{0, 0};
    int[] left  = dfs(node.left);
    int[] right = dfs(node.right);
    int robCurrent  = node.val + left[1] + right[1];    // rob this: skip children
    int skipCurrent = Math.max(left[0], left[1])        // skip this: children optimal
                    + Math.max(right[0], right[1]);
    return new int[]{robCurrent, skipCurrent};
}

int cameras = 0;

public int minCameraCover(TreeNode root) {
    // If root is not covered after DFS, add one more camera
    return (dfs(root) == 0 ? 1 : 0) + cameras;
}

// Returns: 0 = not covered, 1 = has camera, 2 = covered by child
private int dfs(TreeNode node) {
    if (node == null) return 2;     // null nodes are considered covered
    int left  = dfs(node.left);
    int right = dfs(node.right);
    if (left == 0 || right == 0) {  // a child is not covered: must place camera here
        cameras++;
        return 1;
    }
    if (left == 1 || right == 1) {  // a child has a camera: current is covered
        return 2;
    }
    return 0;                       // both children covered but no camera below: not covered
}

int moves = 0;

public int distributeCoins(TreeNode root) {
    dfs(root);
    return moves;
}

// Returns excess coins in subtree (positive = surplus, negative = deficit)
private int dfs(TreeNode node) {
    if (node == null) return 0;
    int leftExcess  = dfs(node.left);
    int rightExcess = dfs(node.right);
    moves += Math.abs(leftExcess) + Math.abs(rightExcess);   // coins crossing edges
    return node.val - 1 + leftExcess + rightExcess;          // excess at this subtree
}

int maxLen = 0;

public int longestZigZag(TreeNode root) {
    dfs(root, false, 0);
    dfs(root, true,  0);
    return maxLen;
}

private void dfs(TreeNode node, boolean goLeft, int length) {
    if (node == null) return;
    maxLen = Math.max(maxLen, length);
    if (goLeft) {
        dfs(node.left,  false, length + 1);  // continue zigzag: go opposite next
        dfs(node.right, true,  1);           // restart zigzag
    } else {
        dfs(node.right, true,  length + 1);
        dfs(node.left,  false, 1);
    }
}

public int goodNodes(TreeNode root) {
    return dfs(root, Integer.MIN_VALUE);
}

private int dfs(TreeNode node, int maxSoFar) {
    if (node == null) return 0;
    int count = (node.val >= maxSoFar) ? 1 : 0;
    maxSoFar = Math.max(maxSoFar, node.val);
    return count + dfs(node.left, maxSoFar) + dfs(node.right, maxSoFar);
}

public String serialize(TreeNode root) {
    StringBuilder sb = new StringBuilder();
    serDFS(root, sb);
    return sb.toString();
}

private void serDFS(TreeNode node, StringBuilder sb) {
    if (node == null) { sb.append("N,"); return; }
    sb.append(node.val).append(",");
    serDFS(node.left,  sb);
    serDFS(node.right, sb);
}

public TreeNode deserialize(String data) {
    String[] tokens = data.split(",");
    int[] idx = {0};                       // mutable index shared across calls
    return desDFS(tokens, idx);
}

private TreeNode desDFS(String[] tokens, int[] idx) {
    if (tokens[idx[0]].equals("N")) { idx[0]++; return null; }
    TreeNode node = new TreeNode(Integer.parseInt(tokens[idx[0]++]));
    node.left  = desDFS(tokens, idx);
    node.right = desDFS(tokens, idx);
    return node;
}

public String serialize(TreeNode root) {
    StringBuilder sb = new StringBuilder();
    preorder(root, sb);
    return sb.toString();
}

private void preorder(TreeNode node, StringBuilder sb) {
    if (node == null) return;
    sb.append(node.val).append(",");
    preorder(node.left,  sb);
    preorder(node.right, sb);
}

public TreeNode deserialize(String data) {
    if (data.isEmpty()) return null;
    String[] tokens = data.split(",");
    int[] idx = {0};
    return build(tokens, idx, Integer.MIN_VALUE, Integer.MAX_VALUE);
}

private TreeNode build(String[] tokens, int[] idx, int min, int max) {
    if (idx[0] == tokens.length) return null;
    int val = Integer.parseInt(tokens[idx[0]]);
    if (val < min || val > max) return null;
    idx[0]++;
    TreeNode node = new TreeNode(val);
    node.left  = build(tokens, idx, min, val);
    node.right = build(tokens, idx, val, max);
    return node;
}

public void flatten(TreeNode root) {
    if (root == null) return;
    flatten(root.left);
    flatten(root.right);
    // Connect flattened left to right
    if (root.left != null) {
        TreeNode leftTail = root.left;
        while (leftTail.right != null) leftTail = leftTail.right;
        leftTail.right = root.right;
        root.right = root.left;
        root.left  = null;
    }
}

public TreeNode trimBST(TreeNode root, int low, int high) {
    if (root == null) return null;
    if (root.val < low)  return trimBST(root.right, low, high);  // prune left subtree
    if (root.val > high) return trimBST(root.left,  low, high);  // prune right subtree
    root.left  = trimBST(root.left,  low, high);
    root.right = trimBST(root.right, low, high);
    return root;
}
